function editCompanyModal(id){
 const c=state.companies.find(x=>Number(x.id)===Number(id));if(!c)return;
 if(Number(c.share??100)<50)throw Error('Edycja wymaga co najmniej 50% udziałów w spółce.');
 const types=[['holding','Holding / centrala'],['technology','Spółka technologiczna'],['ai','Laboratorium AI'],['browser','Producent przeglądarek'],['os','Systemy operacyjne'],['database','Bazy danych'],['cloud','Chmura i centra danych'],['search','Wyszukiwarka i reklama'],['security','Cyberbezpieczeństwo'],['chips','Półprzewodniki'],['robotics','Robotyka i automatyka'],['software','Software house / SaaS'],['devtools','Narzędzia developerskie'],['mobile','Systemy mobilne'],['productivity','Oprogramowanie biurowe'],['gaming','Silniki gier'],['devices','Urządzenia i elektronika'],['telecom','Telekomunikacja'],['biotech','Biotechnologia'],['xr','Technologie XR'],['logistics','Infrastruktura i logistyka'],['operating','Spółka operacyjna']];
 const typeOptions=types.map(([v,n])=>'<option value="'+v+'" '+(v===(c.companyType||'operating')?'selected':'')+'>'+n+'</option>').join('');
 const focusOptions=TECHNOLOGY_FOCI.map(x=>'<option value="'+x.id+'" '+(x.id===(c.techFocus||'os')?'selected':'')+'>'+esc(x.name)+'</option>').join('');
 const parents=state.companies.filter(x=>Number(x.id)!==Number(id)&&Number(x.share??100)>=50&&!isDescendant(x.id,id));
 const parentOptions='<option value="">Wilk Investments — poziom główny</option>'+parents.map(x=>'<option value="'+x.id+'" '+(Number(x.id)===Number(c.parentCompanyId)?'selected':'')+'>'+esc(x.name)+'</option>').join('');
 const selectedCountries=Array.isArray(c.operatingCountries)&&c.operatingCountries.length?c.operatingCountries:['Polska'];
 const staff=Math.max(0,Math.floor(Number(c.techStaff??c.employees)||0)),employees=Math.max(staff,Math.floor(Number(c.employees)||0));
 const remaining=Math.max(0,Math.round(Number(c.managementBudgetRemaining??c.managementBudget)||0));
 const spent=Math.max(0,Math.round(Number(c.managementBudgetSpent)||0));
 const section=(num,title,body)=>'<section class="company-create-section"><div class="section-kicker">'+num+' / '+title+'</div>'+body+'</section>';
 const fields=
 '<div class="company-create-grid">'+
 section('01','TOŻSAMOŚĆ I PROFIL','<div class="field"><label>NAZWA SPÓŁKI</label><input id="fName" maxlength="48" value="'+esc(c.name)+'"></div><div class="field"><label>ROLA W GRUPIE</label><select id="fCompanyType">'+typeOptions+'</select></div><div class="field"><label>BRANŻA / RYNEK</label><input id="fIndustry" maxlength="64" value="'+esc(c.industry||'Technologie')+'" placeholder="np. Oprogramowanie dla firm"></div><div class="field"><label>SPECJALIZACJA TECHNOLOGICZNA</label><select id="fTechFocus">'+focusOptions+'</select></div>')+
 section('02','STRUKTURA WŁAŚCICIELSKA','<div class="field"><label>SPÓŁKA NADRZĘDNA</label><select id="fParent">'+parentOptions+'</select><small>Nie można przenieść spółki pod nią samą ani pod jej spółkę córkę.</small></div><div class="notice">Udział holdingu: <b>'+percent(c.share??100)+'</b> · status: <b>'+((Number(c.share??100)>=50)?'kontrola':'mniejszość')+'</b></div><div class="field"><label>STRATEGIA</label><select id="fStrategy"><option value="balanced" '+((c.strategy||'balanced')==='balanced'?'selected':'')+'>Zrównoważony rozwój</option><option value="expansion" '+(c.strategy==='expansion'?'selected':'')+'>Agresywna ekspansja</option><option value="profit" '+(c.strategy==='profit'?'selected':'')+'>Maksymalizacja zysku</option><option value="technology" '+(c.strategy==='technology'?'selected':'')+'>Dominacja technologiczna</option></select></div>')+
 section('03','ZESPÓŁ I KAPITAŁ','<div class="field"><label>ŁĄCZNA LICZBA PRACOWNIKÓW</label><input id="fEmployees" type="number" min="0" max="100000" step="1" value="'+employees+'"></div><div class="field"><label>SPECJALIŚCI TECHNOLOGICZNI</label><input id="fTechStaff" type="number" min="0" max="100000" step="1" value="'+staff+'"><small>Pracownicy przypisani do rozwoju technologii i produktów.</small></div><div class="field"><label>DOSTĘPNY BUDŻET ROZWOJOWY (ZŁ)</label><input id="fCompanyBudget" type="number" min="0" max="1000000000" step="10000" value="'+remaining+'"></div><div class="notice">Wydano dotychczas: <b>'+money(spent)+'</b> · dostępna gotówka holdingu: <b>'+money(state.cash)+'</b>. Zwiększenie budżetu pobiera gotówkę, zmniejszenie ją zwraca.</div>')+
 section('04','AUTONOMIA I AUTOMATYZACJA','<label class="company-edit-toggle"><input id="fAutoHire" type="checkbox" '+(c.autoHire!==false?'checked':'')+'> <span><b>Automatyczna rekrutacja</b><small>Spółka samodzielnie zatrudnia specjalistów.</small></span></label><label class="company-edit-toggle"><input id="fAutoProducts" type="checkbox" '+(c.autoProductDevelopment!==false?'checked':'')+'> <span><b>Samodzielne tworzenie produktów</b><small>Spółka projektuje i wprowadza nowe produkty.</small></span></label><label class="company-edit-toggle"><input id="fAutoDevelopment" type="checkbox" '+(c.autoDevelopment!==false?'checked':'')+'> <span><b>Automatyczne ulepszanie</b><small>Spółka finansuje rozwój i aktualizacje istniejących produktów.</small></span></label>')+
 '</div><div class="company-create-section company-edit-markets"><div class="section-kicker">05 / RYNKI DZIAŁALNOŚCI</div>'+continentPicker()+'<div class="field"><label>KRAJE, W KTÓRYCH DZIAŁA SPÓŁKA</label><select id="fCountries" multiple size="8">'+countries.map(x=>'<option value="'+esc(x)+'" '+(selectedCountries.includes(x)?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select><small>Możesz zaznaczyć kilka krajów, cały kontynent albo cały świat.</small></div></div>';
 openModal('Edytor spółki · '+esc(c.name),'Zarządzaj profilem, strukturą grupy, zespołem, budżetem, automatyzacją i rynkami w jednym panelu.',fields,()=>{
  const name=$('fName').value.trim(),industry=$('fIndustry').value.trim(),companyType=$('fCompanyType').value,focus=$('fTechFocus').value,parentValue=$('fParent').value,parentCompanyId=parentValue?Number(parentValue):null,strategy=$('fStrategy').value,employees=Number($('fEmployees').value),techStaff=Number($('fTechStaff').value),budget=Number($('fCompanyBudget').value),selected=[...$('fCountries').selectedOptions].map(o=>o.value);
  if(name.length<2||name.length>48)throw Error('Nazwa spółki musi mieć od 2 do 48 znaków.');
  if(!industry||industry.length>64)throw Error('Podaj prawidłową branżę.');
  if(!Number.isInteger(employees)||employees<0||employees>100000)throw Error('Podaj prawidłową liczbę pracowników.');
  if(!Number.isInteger(techStaff)||techStaff<0||techStaff>employees)throw Error('Liczba specjalistów technologicznych nie może przekraczać łącznego zatrudnienia.');
  if(!Number.isSafeInteger(budget)||budget<0||budget>1000000000)throw Error('Budżet musi wynosić od 0 do 1 000 000 000 zł.');
  if(!selected.length)throw Error('Wybierz przynajmniej jeden kraj działalności.');
  if(parentCompanyId===Number(id)||parentCompanyId!=null&&isDescendant(parentCompanyId,Number(id)))throw Error('Nieprawidłowa struktura właścicielska — wykryto cykl.');
  if(parentCompanyId!=null&&!state.companies.some(x=>Number(x.id)===parentCompanyId&&Number(x.share??100)>=50))throw Error('Wybrana spółka nadrzędna nie jest dostępna.');
  const currentRemaining=Math.max(0,Number(c.managementBudgetRemaining??c.managementBudget)||0),delta=budget-currentRemaining;
  if(delta>state.cash)throw Error('Za mało gotówki na zwiększenie budżetu spółki. Brakuje '+money(delta-state.cash)+'.');
  const oldName=c.name;
  state.cash-=delta;c.name=name;c.companyType=companyType;c.industry=industry;c.techFocus=focus;c.strategy=strategy;c.parentCompanyId=parentCompanyId;c.employees=employees;c.techStaff=techStaff;c.managementBudgetRemaining=budget;c.managementBudget=spent+budget;c.managementBudgetSpent=spent;c.autoHire=$('fAutoHire').checked;c.autoProductDevelopment=$('fAutoProducts').checked;c.autoDevelopment=$('fAutoDevelopment').checked;c.operatingCountries=selected;
  let staffLeft=techStaff;(c.techProducts||[]).forEach(p=>{const assigned=Math.max(0,Math.floor(Number(p.staffAssigned)||0));p.staffAssigned=Math.min(assigned,staffLeft);staffLeft-=p.staffAssigned;});
  state.shops.filter(shop=>Number(shop.companyId)===Number(id)).forEach(shop=>{const current=String(shop.name||'').trim();shop.name=current.startsWith(oldName)?name+current.slice(oldName.length):name+' — '+current;});
  const listed=state.market.find(x=>Number(x.subsidiaryId)===Number(id));if(listed){listed.name=name;listed.sector=industry;}
  log('✏️','Zaktualizowano profil spółki',oldName+' → '+name+' · '+companyType+' · '+selected.length+' rynków');
  if(delta)moneyFx(-delta,'budżet spółki');
  closeModal();save();safeRender();notify('Zapisano wszystkie ustawienia spółki.');
 });
 bindContinentPicker();
}
function closeCompanyModal(id){const c=state.companies.find(x=>x.id===id);if(!c)return;const children=state.companies.filter(x=>x.parentCompanyId===id).length,shops=state.shops.filter(x=>x.companyId===id).length,refund=Math.round(c.value*.25);openModal('Zamknij spółkę','Spółka zostanie usunięta. Jej sklepy i spółki córki przejdą do spółki nadrzędnej (lub holdingu głównego).', '<div class="notice">'+esc(c.name)+'<br>'+shops+' sklepów · '+children+' spółek córek<br>Odzyskasz '+money(refund)+' (25% wartości).</div>',()=>{const parent=c.parentCompanyId??null;state.shops.filter(x=>x.companyId===id).forEach(x=>x.companyId=parent);state.companies.filter(x=>x.parentCompanyId===id).forEach(x=>x.parentCompanyId=parent);state.companies=state.companies.filter(x=>x.id!==id);state.cash+=refund;moneyFx(refund,'likwidacja spółki');log('🚪','Zamknięto spółkę',c.name+' · odzyskano '+money(refund));moneyFx(refund,'likwidacja spółki');closeModal();save();safeRender();notify('Spółka została zamknięta.');});}
function assignShopModal(shopId){const shop=state.shops.find(s=>s.id===shopId);if(!shop)return;openModal('Przypisz sklep do spółki','Przeniesienie sklepu wewnątrz grupy jest bezpłatne.', '<div class="field"><label>SKLEP</label><input disabled value="'+esc(shop.name)+'"></div><div class="field"><label>NOWY WŁAŚCICIEL</label><select id="fOwner">'+state.companies.filter(c=>c.share>=50).map(c=>'<option value="'+c.id+'" '+(c.id===shop.companyId?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></div>',()=>{const owner=state.companies.find(c=>c.id===Number($('fOwner').value));if(!owner)throw Error('Brak spółki z kontrolnym pakietem.');shop.companyId=owner.id;log('🏬','Przypisano sklep',shop.name+' → '+owner.name);closeModal();save();safeRender();notify('Sklep przypisany do spółki.');});}
function assignCompanyModal(companyId){const company=state.companies.find(c=>c.id===companyId);if(!company)return;openModal('Przenieś spółkę do innej spółki','Możesz zagnieżdżać spółki bez ograniczenia poziomów. Nie można przypisać spółki do niej samej ani do jej potomka.', '<div class="field"><label>SPÓŁKA</label><input disabled value="'+esc(company.name)+'"></div><div class="field"><label>NOWA SPÓŁKA NADRZĘDNA</label><select id="fParent"><option value="">Wilk Investments — poziom główny</option>'+state.companies.filter(c=>c.id!==company.id&&c.share>=50&&!isDescendant(c.id,company.id)).map(c=>'<option value="'+c.id+'" '+(c.id===company.parentCompanyId?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></div>',()=>{const value=$('fParent').value;company.parentCompanyId=value?Number(value):null;log('◈','Zmieniono strukturę grupy',company.name);closeModal();save();safeRender();notify('Zmieniono spółkę nadrzędną.');});}
function isDescendant(candidateId,parentId,seen=new Set()){if(seen.has(candidateId))return true;seen.add(candidateId);const c=state.companies.find(x=>x.id===candidateId);if(!c||c.parentCompanyId==null)return false;if(c.parentCompanyId===parentId)return true;return isDescendant(c.parentCompanyId,parentId,seen);}

