document.addEventListener('click',e=>{const target=e.target instanceof Element?e.target:null;const toggle=target?.closest('.nav-folder-toggle');if(!toggle)return;e.preventDefault();const expanded=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!expanded));const panel=document.getElementById(toggle.getAttribute('aria-controls'));if(panel)panel.classList.toggle('is-collapsed',expanded);},true);
document.addEventListener('click',e=>{const target=e.target instanceof Element?e.target:null;if(!target)return;const action=target.closest('[data-action]');const page=target.closest('[data-page]');if(action){if(action.disabled||action.getAttribute('aria-disabled')==='true')return;e.preventDefault();handleAction(action);return;}if(page){e.preventDefault();const folder=page.closest('.nav-folder');if(folder){const toggle=folder.querySelector('.nav-folder-toggle');const panel=folder.querySelector('.nav-folder-items');if(toggle)toggle.setAttribute('aria-expanded','true');if(panel)panel.classList.remove('is-collapsed');}showPage(page.dataset.page);}},true);
document.addEventListener('change',e=>{if(e.target.matches('[data-factory-owner]')){const factory=state.factories.find(f=>f.id===Number(e.target.dataset.factoryId));const company=state.companies.find(c=>c.id===Number(e.target.value)&&c.share>=50);if(factory&&company){factory.companyId=company.id;save();safeRender();notify('Zmieniono właściciela fabryki.');}}if(e.target.matches('[data-shop-owner]')){const shop=state.shops.find(s=>s.id===Number(e.target.dataset.shopOwner));if(shop){shop.companyId=Number(e.target.value)||null;save();notify('Zmieniono właściciela sklepu.');}}if(e.target.matches('[data-shop-brand]')){const shop=state.shops.find(s=>s.id===Number(e.target.dataset.shopBrand));if(shop){const brandId=Number(e.target.value)||null;const brand=state.companies.flatMap(c=>c.ownBrands||[]).find(x=>x.id===brandId);if(brandId&&!brand)throw new Error('Nie znaleziono marki własnej.');shop.brandId=brandId;save();safeRender();notify(brand?'Przypisano markę '+brand.name+' do sklepu.':'Usunięto markę własną ze sklepu.');}}});
$('modalClose').addEventListener('click',closeModal);$('modalCancel').type='button';$('modalCancel').addEventListener('click',e=>{e.preventDefault();closeModal();});$('modalConfirm').type='button';$('modalConfirm').addEventListener('click',e=>{e.preventDefault();if(!modalAction)return;try{modalAction();}catch(error){notify(error.message||'Błąd formularza.');}});$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal();});
function safeRender(){try{renderAll(state);}catch(error){console.error('Market Tycoon — render error:',error);const panel=$('page-overview');if(panel)panel.innerHTML='<div class="card"><h2>Nie udało się wczytać pulpitu</h2><p>Gra wykryła niezgodność zapisu lub błąd widoku. Dane zapisu pozostają zachowane.</p><button class="button button-primary" id="repairSave">Napraw widok i odśwież</button><p style="font-size:11px;color:#9fb4c1">Szczegóły błędu: '+esc(error?.message||error)+'</p></div>';const repair=$('repairSave');if(repair)repair.addEventListener('click',()=>{location.reload();});showPage('overview');}}
function advanceDay(){
 const r=simulateGameDay(state);
 if(r.finances.event)notify(r.finances.event.icon+' '+r.finances.event.title);
 if(r.initiatives?.total)log('🏢','Efekt inwestycji','Dodatkowy wynik: '+money(r.initiatives.total));
 if(r.market.listed)notify('Debiut giełdowy: '+r.market.listed.name);
 log('📊','Dzień '+state.day+' rozliczony',(r.finances.profit>=0?'+':'−')+money(Math.abs(r.finances.profit)));
 moneyFx(state.cash-(lastCashBeforeDay??state.cash),'wynik dnia');
 lastCashBeforeDay=state.cash;
 save();safeRender();
}
let lastCashBeforeDay=state.cash;
const gameClock=createGameClock(advanceDay,{dayLengthMs:30000,initialSpeed:1});
function setTimeSpeed(speed){
 const current=gameClock.setSpeed(speed);
 document.querySelectorAll('[data-speed]').forEach(b=>{const active=Number(b.dataset.speed)===current;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 const status=$('timeStatus');if(status)status.textContent=current===0?'PAUZA':current+'× · '+(30/current)+' s/dzień';
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-speed]');if(b){e.preventDefault();setTimeSpeed(Number(b.dataset.speed));}},true);
setTimeSpeed(1);
window.__marketTycoonEngineReady=true;
safeRender();showPage('overview');window.addEventListener('error',e=>{console.error('Market Tycoon:',e.message,e.filename,e.lineno);notify('Wystąpił błąd gry. Odśwież stronę; szczegóły są w konsoli.');});window.addEventListener('unhandledrejection',e=>{console.error('Market Tycoon:',e.reason);notify('Nie udało się wykonać operacji.');});
